const msg = $input.first().json.message || {};
const text = (msg.text || '').trim();
const chatId = msg.chat?.id;
if (!text.startsWith('/')) return [{ json: { chatId, text: 'Send a command starting with /' } }];

const parts = text.split(/\s+/);
const rawCmd = parts[0].replace('/', '').toLowerCase();
const args = parts.slice(1);
const BASE = 'http://host.docker.internal:8000';
const urg = { hot: '\u{1F534}', active: '\u{1F7E1}', aging: '\u26AA', stale: '\u{1F480}' };

async function api(method, path, body) {
  try {
    const opts = { method };
    if (body) { opts.headers = { 'Content-Type': 'application/json' }; opts.body = JSON.stringify(body); }
    const res = await fetch(BASE + path, opts);
    return await res.json();
  } catch(e) { return { error: String(e) }; }
}

let cmd = rawCmd;
let a = args;
if (cmd === 'add' && args[0]) { cmd = 'add_' + args[0].toLowerCase(); a = args.slice(1); }

let reply = '';

if (cmd === 'jobs') {
  const jobs = await api('GET', '/jobs?status=new&min_score=3.5&limit=5');
  const list = Array.isArray(jobs) ? jobs : [];
  if (!list.length) { reply = 'No new jobs right now.'; }
  else {
    const lines = list.map(j => `${urg[j.urgency]||'\u26AA'} *${j.title}* @ ${j.company} (${(j.score||0).toFixed(1)}\u2605)\n  ${j.location||'N/A'} | /job ${j.id}`);
    reply = `\u{1F5C2} *Top new jobs:*\n\n${lines.join('\n\n')}`;
  }
} else if (cmd === 'job') {
  const j = await api('GET', `/jobs/${a[0]}`);
  if (!j || !j.id) { reply = 'Job not found.'; }
  else {
    let d = {};
    try { d = typeof j.score_detail==='string' ? JSON.parse(j.score_detail) : (j.score_detail||{}); } catch(e){}
    const matched = (d.matched_skills||[]).join(', ')||'N/A';
    const missing = (d.missing_skills||[]).join(', ')||'None';
    reply = `${urg[j.urgency]||'\u26AA'} *${j.title}* @ ${j.company}\n${j.location||'N/A'} | Score: ${(j.score||0).toFixed(1)}\u2605 | ${j.status}\n\n\u{1F4A1} ${d.fit_summary||'No summary.'}\n\n\u2705 Matched: ${matched}\n\u274C Missing: ${missing}\n\n/apply ${j.id}`;
  }
} else if (cmd === 'apply') {
  const r = await api('POST', `/jobs/${a[0]}/apply`);
  reply = r.ok ? `\u2705 Applied to *${r.title}* @ ${r.company}\nFollow-up set for ${r.follow_up_due}.` : `\u274C ${r.detail||'Error'}`;
} else if (cmd === 'interview') {
  await api('POST', `/jobs/${a[0]}/outcome`, {outcome:'interview'});
  reply = '\u{1F389} *Interview!* Marked. Good luck!';
} else if (cmd === 'offer') {
  await api('POST', `/jobs/${a[0]}/outcome`, {outcome:'offer'});
  reply = '\u{1F38A} *OFFER received!* Congratulations!';
} else if (cmd === 'rejected') {
  await api('POST', `/jobs/${a[0]}/outcome`, {outcome:'rejected', rejection_reason: a.slice(1).join(' ')||null});
  reply = '\u{1F44E} Marked as rejected. On to the next one.';
} else if (cmd === 'ghosted') {
  await api('POST', `/jobs/${a[0]}/outcome`, {outcome:'ghosted'});
  reply = '\u{1F47B} Marked as ghosted.';
} else if (cmd === 'note') {
  await api('POST', `/jobs/${a[0]}/note`, {text: a.slice(1).join(' ')});
  reply = '\u{1F4DD} Note saved.';
} else if (cmd === 'blacklist') {
  await api('POST', `/companies/blacklist?name=${encodeURIComponent(a.join(' '))}`);
  reply = '\u{1F6AB} Company blacklisted. No more alerts from them.';
} else if (cmd === 'add_company') {
  await api('POST', '/companies', {name:a[0], careers_url:a[1]||'', linkedin_slug:a[2]||''});
  reply = '\u{1F3E2} Company added to watchlist.';
} else if (cmd === 'add_role') {
  await api('POST', '/roles', {title: a.join(' ')});
  reply = '\u{1F3AF} Role added to watchlist.';
} else if (cmd === 'stats') {
  const s = await api('GET', '/stats');
  reply = `\u{1F4CA} *Career Scout Stats*\n\nTotal: ${s.total}\nNew: ${s.new}\nApplied: ${s.applied}\nInterviews: ${s.interviews}\nOffers: ${s.offers}\nUnscored: ${s.unscored}`;
} else if (cmd === 'scout') {
  await api('POST', '/scout');
  reply = '\u{1F50D} Scout started. Watch for alerts!';
} else if (cmd === 'resume') {
  const r = await api('POST', `/forge/${a[0]}`);
  reply = r.telegram_message || r.error || 'Resume generation failed.';
} else if (cmd === 'digest') {
  const jobs = await api('GET', '/jobs/digest?limit=5');
  const list = Array.isArray(jobs) ? jobs : [];
  if (!list.length) { reply = 'No high-scoring jobs today.'; }
  else {
    const lines = list.map(j => `${urg[j.urgency]||'\u26AA'} *${j.title}* @ ${j.company} (${(j.score||0).toFixed(1)}\u2605)\n  ${j.location||'N/A'} | /job ${j.id}`);
    reply = `\u2600\uFE0F *Today's top matches:*\n\n${lines.join('\n\n')}\n\nReply /jobs for full list.`;
  }
} else {
  reply = '\u2753 Unknown command.\n\nAvailable:\n/jobs /job <id> /apply <id>\n/interview <id> /offer <id>\n/rejected <id> /ghosted <id>\n/note <id> <text> /blacklist <name>\n/add company <name> <url>\n/add role <title>\n/stats /scout /digest /resume <id>';
}

return [{ json: { chatId, text: reply } }];
